--
-- Name: upsert_exercise_prs(uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_exercise_prs(p_user_id uuid, p_exercise_id uuid, p_workout_started_at timestamp with time zone, p_equipment_type text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_default_eq   text;
  v_equipment    text;
  v_max_weight   numeric(10,2);
  v_1rm_estimate numeric(10,2);
  v_session_vol  numeric(10,2);
BEGIN
  -- Default tool of the exercise (NULL when not linked to the library)
  SELECT ed.equipment_type
  INTO v_default_eq
  FROM exercises ex
  JOIN exercise_definitions ed ON ed.id = ex.exercise_definition_id
  WHERE ex.id = p_exercise_id
    AND ex.user_id = p_user_id;

  v_equipment := COALESCE(p_equipment_type, v_default_eq);

  -- max_weight and session volume from completed non-warmup sets done with this tool
  SELECT
    MAX(se.weight_kg),
    SUM(se.weight_kg * se.reps)
  INTO v_max_weight, v_session_vol
  FROM set_entries se
  JOIN workout_exercise_entries wee ON wee.id = se.workout_exercise_entry_id
  JOIN workouts w ON w.id = wee.workout_id
  WHERE wee.exercise_id    = p_exercise_id
    AND wee.user_id        = p_user_id
    AND COALESCE(wee.equipment_type, v_default_eq) IS NOT DISTINCT FROM v_equipment
    AND se.completed       = true
    AND se.is_warmup       = false
    AND se.weight_kg       IS NOT NULL
    AND se.reps            IS NOT NULL
    AND se.reps            > 0
    AND w.started_at       = p_workout_started_at;

  -- 1RM estimate: Epley restricted to 1–12 reps (see migration 015)
  SELECT
    MAX(
      CASE
        WHEN se.reps = 1 THEN se.weight_kg
        ELSE se.weight_kg * (1.0 + se.reps::numeric / 30.0)
      END
    )
  INTO v_1rm_estimate
  FROM set_entries se
  JOIN workout_exercise_entries wee ON wee.id = se.workout_exercise_entry_id
  JOIN workouts w ON w.id = wee.workout_id
  WHERE wee.exercise_id    = p_exercise_id
    AND wee.user_id        = p_user_id
    AND COALESCE(wee.equipment_type, v_default_eq) IS NOT DISTINCT FROM v_equipment
    AND se.completed       = true
    AND se.is_warmup       = false
    AND se.weight_kg       IS NOT NULL
    AND se.reps            IS NOT NULL
    AND se.reps            BETWEEN 1 AND 12
    AND w.started_at       = p_workout_started_at;

  IF v_max_weight IS NOT NULL THEN
    INSERT INTO exercise_prs (user_id, exercise_id, pr_type, equipment_type, value, achieved_at)
    VALUES (p_user_id, p_exercise_id, 'max_weight', v_equipment, v_max_weight, p_workout_started_at)
    ON CONFLICT ON CONSTRAINT exercise_prs_user_exercise_type_equipment_key
    DO UPDATE SET
      value       = GREATEST(exercise_prs.value, EXCLUDED.value),
      achieved_at = CASE WHEN EXCLUDED.value > exercise_prs.value
                         THEN EXCLUDED.achieved_at
                         ELSE exercise_prs.achieved_at END,
      updated_at  = now();
  END IF;

  IF v_1rm_estimate IS NOT NULL THEN
    INSERT INTO exercise_prs (user_id, exercise_id, pr_type, equipment_type, value, achieved_at)
    VALUES (p_user_id, p_exercise_id, '1rm_estimate', v_equipment, v_1rm_estimate, p_workout_started_at)
    ON CONFLICT ON CONSTRAINT exercise_prs_user_exercise_type_equipment_key
    DO UPDATE SET
      value       = GREATEST(exercise_prs.value, EXCLUDED.value),
      achieved_at = CASE WHEN EXCLUDED.value > exercise_prs.value
                         THEN EXCLUDED.achieved_at
                         ELSE exercise_prs.achieved_at END,
      updated_at  = now();
  END IF;

  IF v_session_vol IS NOT NULL THEN
    INSERT INTO exercise_prs (user_id, exercise_id, pr_type, equipment_type, value, achieved_at)
    VALUES (p_user_id, p_exercise_id, 'max_volume', v_equipment, v_session_vol, p_workout_started_at)
    ON CONFLICT ON CONSTRAINT exercise_prs_user_exercise_type_equipment_key
    DO UPDATE SET
      value       = GREATEST(exercise_prs.value, EXCLUDED.value),
      achieved_at = CASE WHEN EXCLUDED.value > exercise_prs.value
                         THEN EXCLUDED.achieved_at
                         ELSE exercise_prs.achieved_at END,
      updated_at  = now();
  END IF;
END;
$$;

--
-- Name: workout_sets_payload(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workout_sets_payload(p_entries jsonb) RETURNS TABLE(entry_id uuid, wde_id uuid, id uuid, set_number integer, weight_kg numeric, reps integer, completed boolean, is_warmup boolean, too_heavy boolean, too_heavy_reps integer)
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (e->>'entryId')::uuid,
         (e->>'workoutDayExerciseId')::uuid,
         (s->>'id')::uuid,
         (s->>'set_number')::int,
         (s->>'weight_kg')::numeric,
         (s->>'reps')::int,
         coalesce((s->>'completed')::boolean, false),
         coalesce((s->>'is_warmup')::boolean, false),
         coalesce((s->>'too_heavy')::boolean, false),
         (s->>'too_heavy_reps')::int
  FROM jsonb_array_elements(p_entries) AS e,
       jsonb_array_elements(coalesce(e->'sets', '[]'::jsonb)) AS s
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: exercise_definitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.exercise_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    normalized_name text NOT NULL,
    aliases text[] DEFAULT '{}'::text[] NOT NULL,
    equipment_type text NOT NULL,
    primary_muscle text NOT NULL,
    secondary_muscles text[] DEFAULT '{}'::text[] NOT NULL,
    movement_pattern text,
    is_bodyweight boolean DEFAULT false NOT NULL,
    is_cardio boolean DEFAULT false NOT NULL,
    is_bilateral boolean DEFAULT true NOT NULL,
    is_main_lift boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT exercise_definitions_equipment_type_check CHECK ((equipment_type = ANY (ARRAY['barbell'::text, 'dumbbell'::text, 'cable'::text, 'machine_plate'::text, 'machine_stack'::text, 'smith'::text, 'bodyweight'::text, 'kettlebell'::text, 'trap_bar'::text, 'band'::text, 'suspension'::text, 'cardio_machine'::text, 'other'::text]))),
    CONSTRAINT exercise_definitions_movement_pattern_check CHECK ((movement_pattern = ANY (ARRAY['horizontal_push'::text, 'vertical_push'::text, 'horizontal_pull'::text, 'vertical_pull'::text, 'squat'::text, 'hinge'::text, 'lunge'::text, 'carry'::text, 'olympic'::text, 'isolation'::text, 'core'::text, 'cardio'::text]))),
    CONSTRAINT exercise_definitions_primary_muscle_check CHECK ((primary_muscle = ANY (ARRAY['chest'::text, 'back_lats'::text, 'back_upper'::text, 'shoulders'::text, 'biceps'::text, 'triceps'::text, 'forearms'::text, 'core'::text, 'glutes'::text, 'quads'::text, 'hamstrings'::text, 'calves'::text])))
);

