--

CREATE TABLE public.set_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workout_exercise_entry_id uuid NOT NULL,
    user_id uuid NOT NULL,
    set_number integer NOT NULL,
    weight_kg numeric(6,2),
    reps integer,
    completed boolean DEFAULT false,
    is_warmup boolean DEFAULT false,
    too_heavy boolean DEFAULT false,
    too_heavy_reps integer,
    created_at timestamp with time zone DEFAULT now()
);

--
-- Name: workout_bonus_cardio; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workout_bonus_cardio (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workout_id uuid NOT NULL,
    user_id uuid NOT NULL,
    machine_type text DEFAULT 'rower'::text NOT NULL,
    distance_m integer,
    duration_seconds numeric(8,1),
    pace_per_500_seconds numeric(8,1),
    calories integer,
    stroke_rate integer,
    avg_watts integer,
    extra_metrics jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT workout_bonus_cardio_machine_type_check CHECK ((machine_type = ANY (ARRAY['rower'::text, 'rowing_machine'::text, 'bike'::text, 'skierg'::text, 'assault_bike'::text, 'elliptical'::text, 'treadmill'::text, 'stair_climber'::text, 'other'::text])))
);

--
-- Name: workout_day_exercises; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workout_day_exercises (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workout_day_id uuid NOT NULL,
    exercise_id uuid NOT NULL,
    user_id uuid NOT NULL,
    order_index integer DEFAULT 0 NOT NULL,
    target_sets integer DEFAULT 3 NOT NULL,
    target_reps integer DEFAULT 5 NOT NULL,
    created_at timestamp with time zone DEFAULT now()
);

--
-- Name: workout_days; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workout_days (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    program_id uuid NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    day_of_week integer,
    day_label text,
    kind text DEFAULT 'legacy'::text,
    day_order integer,
    weekday_label text,
    session_label text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT workout_days_kind_check CHECK ((kind = ANY (ARRAY['weekday'::text, 'session'::text, 'legacy'::text])))
);

